const MG_INSTRUCTOR_LINE='Feed your flame with a touch, and hold it gentle — too bright breaks them, too dim loses them.';
const MG={active:false,shown_tip:false,t:0,flame:0.5,target:0.5,target_drift_t:0,nomads:[],entry_t:0,exit_t:0,won:false,failed:false,fail_reason:'',pulse:0,afterglow:0,conv:[],band:[],cue_t:0};
function mgInit(st,count){const s=st||MG;const _n=Math.max(3,Math.min(8,count||8));s.active=false;s.shown_tip=false;s.t=0;s.flame=0.5;s.target=0.5;s.target_drift_t=0;s.nomads=[];for(let i=0;i<_n;i++){const a=i*Math.PI*2/_n;s.nomads.push({a:a,d:180,commit:0.5,alive:true});}s.entry_t=0;s.exit_t=0;s.won=false;s.failed=false;s.fail_reason='';s.pulse=0;s.afterglow=0;s.conv=[];s.cue_t=0;return s;}
function mgStep(s,clicked,dt){if(s.exit_t>0){s.exit_t+=dt;return s;}s.t+=dt;if(s.entry_t<90){s.entry_t+=dt;return s;}if(clicked)s.flame=Math.min(1,s.flame+0.18);s.flame=Math.max(0,s.flame-0.0005*dt);s.target_drift_t+=dt;if(s.target_drift_t>120){s.target_drift_t=0;s.target=0.45+Math.random()*0.15;}const inBand=s.flame>=s.target-0.08&&s.flame<=s.target+0.12;let allClose=true,anyAlive=false;for(const n of s.nomads){if(!n.alive)continue;anyAlive=true;if(s.flame>s.target+0.25){n.commit=Math.max(0,n.commit-0.004*dt);if(n.commit<0.2){n.alive=false;s.failed=true;s.fail_reason='bright';}}else if(s.flame<s.target-0.15){n.commit=Math.max(0,n.commit-0.001*dt);if(n.commit<0.25){n.alive=false;s.failed=true;s.fail_reason='dim';}}else if(inBand){n.commit=Math.min(1,n.commit+0.008*dt);n.d=Math.max(32,n.d-0.25*dt);}else{n.d=Math.max(32,n.d-0.08*dt);}if(n.d>32)allClose=false;}if(!anyAlive&&!s.won){s.failed=true;if(!s.fail_reason)s.fail_reason='dim';}if(allClose&&anyAlive&&!s.failed){s.won=true;s.exit_t=1;}if(s.failed&&s.exit_t===0)s.exit_t=1;return s;}

/* ===== THE CAVE — the narrated opening's first moment (GDD §3 NICE #1, A4 beat n1):
   the undetermined white flame, the stone it lights, and the two mouths. A whole
   section before the main game: your pole is chosen by which mouth you WALK out of.
   Self-contained DOM canvas overlay — touches no Phaser internals. ===== */
const CAVE_LINE='You carry a white flame that lights only the stone around you — it becomes whatever you do with it.';
const CAVE={active:false,done:false,px:0,py:0,fade:0,keys:{},raf:0,cv:null,ctx:null,W:0,H:0,R:0,dots:null,t:0,exitPole:0};
function caveKeyD(e){const k=e.key.toLowerCase();if(k==='w'||k==='a'||k==='s'||k==='d'){CAVE.keys[k]=true;e.preventDefault();}}
function caveKeyU(e){const k=e.key.toLowerCase();CAVE.keys[k]=false;}
function caveMouth(a){const t=(a%(Math.PI*2)+Math.PI*2)%(Math.PI*2);const w=0.42;
 if(Math.min(t,Math.PI*2-t)<w)return 1;if(Math.abs(t-Math.PI)<w)return -1;return 0;}
function caveStart(){
 const gc=document.querySelector('canvas');
 if(!gc){CAVE.done=true;newGame(1);return;}
 const r=gc.getBoundingClientRect();
 const cv=document.createElement('canvas');cv.width=r.width;cv.height=r.height;
 cv.style.cssText='position:fixed;left:'+r.left+'px;top:'+r.top+'px;width:'+r.width+'px;height:'+r.height+'px;z-index:50;';
 document.body.appendChild(cv);
 CAVE.cv=cv;CAVE.ctx=cv.getContext('2d');CAVE.W=r.width;CAVE.H=r.height;
 CAVE.R=Math.min(r.width,r.height)*0.34;CAVE.px=0;CAVE.py=0;CAVE.active=true;CAVE.t=0;CAVE.fade=0;CAVE.exitPole=0;
 CAVE.dots=[];for(let i=0;i<1100;i++){const a=Math.random()*Math.PI*2,d=Math.sqrt(Math.random())*CAVE.R;CAVE.dots.push([Math.cos(a)*d,Math.sin(a)*d,Math.random()]);}
 document.addEventListener('keydown',caveKeyD,true);document.addEventListener('keyup',caveKeyU,true);
 CAVE.raf=requestAnimationFrame(caveFrame);
}
function caveFrame(ts){
 if(!CAVE.active)return;
 const dt=Math.max(0.5,Math.min(3,((ts-(CAVE.lts||ts))||16.7)/16.7));CAVE.lts=ts;
 const c=CAVE.ctx,W=CAVE.W,H=CAVE.H,cx=W/2,cy=H/2;CAVE.t++;
 let vx=(CAVE.keys.d?1:0)-(CAVE.keys.a?1:0),vy=(CAVE.keys.s?1:0)-(CAVE.keys.w?1:0);
 if(vx||vy){const m=Math.hypot(vx,vy);CAVE.px+=vx/m*2.4*dt;CAVE.py+=vy/m*2.4*dt;}
 const pd=Math.hypot(CAVE.px,CAVE.py),pa=Math.atan2(CAVE.py,CAVE.px);
 const mouth=caveMouth(pa);
 if(pd>CAVE.R-12&&!mouth){const k=(CAVE.R-12)/pd;CAVE.px*=k;CAVE.py*=k;}
 if(pd>CAVE.R+26&&mouth&&!CAVE.exitPole)CAVE.exitPole=mouth;
 c.fillStyle='#000';c.fillRect(0,0,W,H);
 const px=cx+CAVE.px,py=cy+CAVE.py;
 const flick=0.9+Math.sin(CAVE.t*0.17)*0.06+Math.sin(CAVE.t*0.05)*0.04;
 const LR=95*flick;
 for(const d of CAVE.dots){const dx=cx+d[0],dy=cy+d[1];const dist=Math.hypot(dx-px,dy-py);
  if(dist<LR){const al=(1-dist/LR)*0.5*(0.4+d[2]*0.6);c.fillStyle='rgba(155,150,140,'+al.toFixed(3)+')';c.fillRect(dx,dy,2,2);}}
 c.lineWidth=10;
 for(let a=0;a<Math.PI*2;a+=0.05){if(caveMouth(a))continue;
  const wx=cx+Math.cos(a)*CAVE.R,wy=cy+Math.sin(a)*CAVE.R;const dist=Math.hypot(wx-px,wy-py);
  if(dist<LR*1.25){const al=(1-dist/(LR*1.25))*0.55;c.strokeStyle='rgba(120,112,100,'+al.toFixed(3)+')';
   c.beginPath();c.arc(cx,cy,CAVE.R,a,a+0.055);c.stroke();}}
 const g1=c.createRadialGradient(cx-CAVE.R,cy,4,cx-CAVE.R,cy,90);g1.addColorStop(0,'rgba(200,60,40,0.30)');g1.addColorStop(1,'rgba(200,60,40,0)');
 c.fillStyle=g1;c.fillRect(cx-CAVE.R-90,cy-90,180,180);
 const g2=c.createRadialGradient(cx+CAVE.R,cy,4,cx+CAVE.R,cy,90);g2.addColorStop(0,'rgba(70,180,90,0.30)');g2.addColorStop(1,'rgba(70,180,90,0)');
 c.fillStyle=g2;c.fillRect(cx+CAVE.R-90,cy-90,180,180);
 const gf=c.createRadialGradient(px,py-8,1,px,py-8,LR);gf.addColorStop(0,'rgba(255,255,255,0.95)');gf.addColorStop(0.12,'rgba(255,255,250,0.55)');gf.addColorStop(1,'rgba(255,255,245,0)');
 c.fillStyle=gf;c.beginPath();c.arc(px,py-8,LR,0,Math.PI*2);c.fill();
 c.fillStyle='rgba(255,255,255,1)';c.beginPath();c.arc(px,py-8,3.5+flick*1.5,0,Math.PI*2);c.fill();
 c.fillStyle='rgba(230,228,220,0.85)';c.fillRect(px-2,py-2,4,10);
 try{setTip(CAVE_LINE);}catch(e){}
 if(CAVE.exitPole){CAVE.fade+=dt;c.fillStyle='rgba(255,255,252,'+Math.min(1,CAVE.fade/70).toFixed(3)+')';c.fillRect(0,0,W,H);
  if(CAVE.fade>=90){caveEnd();return;}}
 CAVE.raf=requestAnimationFrame(caveFrame);
}
function caveEnd(){
 CAVE.active=false;CAVE.done=true;CAVE.wake=75;
 document.removeEventListener('keydown',caveKeyD,true);document.removeEventListener('keyup',caveKeyU,true);
 if(CAVE.cv&&CAVE.cv.parentNode)CAVE.cv.parentNode.removeChild(CAVE.cv);
 newGame(CAVE.exitPole||1);
}

{const _origNG=newGame;newGame=function(pole){if(!CAVE.done){if(!CAVE.active)caveStart();return;}_origNG(pole);if(location.hash.includes('mg')){const g=SIM.npcs.filter(x=>x.tribe===-1&&!x.burn).slice(0,6);let i=0;for(const x of g){const a=i*Math.PI/3;x.pos=[Math.max(1,Math.min(46,Math.round(SIM.player_pos[0]+Math.cos(a)*5))),Math.max(1,Math.min(46,Math.round(SIM.player_pos[1]+Math.sin(a)*5)))];i++;}}};}
